import{_ as t,o as e,c as s,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"00-4 零基础排错手册：照着做却跑不通怎么办？","description":"","frontmatter":{},"headers":[],"relativePath":"00-start/troubleshooting.md","filePath":"00-start/troubleshooting.md","lastUpdated":1791601077000}'),n={name:"00-start/troubleshooting.md"};function o(r,a,l,d,p,h){return e(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="_00-4-零基础排错手册-照着做却跑不通怎么办" tabindex="-1">00-4 零基础排错手册：照着做却跑不通怎么办？ <a class="header-anchor" href="#_00-4-零基础排错手册-照着做却跑不通怎么办" aria-label="Permalink to &quot;00-4 零基础排错手册：照着做却跑不通怎么办？&quot;">​</a></h1><blockquote><p><strong>什么时候看</strong>：你在 <a href="/00-start/environment">Remix 实操课</a> 或 <a href="/03-foundry/">Foundry 入门课</a> 遇到错误时，不用把全部知识重新学一遍。按“现象 → 原因 → 最短修复路径”查。</p><p><strong>安全原则</strong>：所有排错先使用 Remix VM 或本地 Foundry，不连接真实资金账户，不把私钥/助记词发给别人。</p></blockquote><h2 id="先确定自己在做哪一种实验" tabindex="-1">先确定自己在做哪一种实验 <a class="header-anchor" href="#先确定自己在做哪一种实验" aria-label="Permalink to &quot;先确定自己在做哪一种实验&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我现在使用什么</th><th>实际运行在哪里</th><th>需要真实钱包吗</th><th>需要真钱吗</th></tr></thead><tbody><tr><td>Remix + <strong>Remix VM</strong></td><td>浏览器内的虚拟链</td><td>不需要</td><td>不需要</td></tr><tr><td>Foundry + <code>forge test</code></td><td>本地测试 EVM</td><td>不需要</td><td>不需要</td></tr><tr><td>Anvil</td><td>本机运行的开发链节点</td><td>不需要真实账户</td><td>不需要</td></tr><tr><td>Remix + Injected Provider</td><td>浏览器钱包连接的指定网络</td><td>需要</td><td>视所选网络而定</td></tr></tbody></table><p><strong>新手先选前三种。</strong> 如果界面突然要求连接钱包或切换主网，检查是否误选了 Injected Provider。</p><h2 id="一、remix-中最常见的-7-种问题" tabindex="-1">一、Remix 中最常见的 7 种问题 <a class="header-anchor" href="#一、remix-中最常见的-7-种问题" aria-label="Permalink to &quot;一、Remix 中最常见的 7 种问题&quot;">​</a></h2><h3 id="问题-1-我打开了网站-却找不到-新建文件" tabindex="-1">问题 1：我打开了网站，却找不到“新建文件” <a class="header-anchor" href="#问题-1-我打开了网站-却找不到-新建文件" aria-label="Permalink to &quot;问题 1：我打开了网站，却找不到“新建文件”&quot;">​</a></h3><p>先在左侧找到 <strong>File Explorer</strong>，不要在 Solidity Compiler 里找文件。新建文件名用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Counter.sol</span></span></code></pre></div><p>后缀 <code>.sol</code> 代表 Solidity 源码文件。文件创建后要把完整合约复制进去，<strong>不能只粘贴函数主体</strong>。</p><h3 id="问题-2-编译器提示版本不兼容" tabindex="-1">问题 2：编译器提示版本不兼容 <a class="header-anchor" href="#问题-2-编译器提示版本不兼容" aria-label="Permalink to &quot;问题 2：编译器提示版本不兼容&quot;">​</a></h3><p>假设源码第一行有：</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pragma</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;"> solidity</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ^0.8.24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p><code>^0.8.24</code> 表示使用兼容的 0.8.x 编译器，不能随便选 0.7.x 或 0.9.x。打开 <strong>Solidity Compiler</strong>，选择与源码兼容的编译器，再点击 <strong>Compile Counter.sol</strong>。</p><p>如果编译失败，不要继续部署；先检查红色错误文本。</p><h3 id="问题-3-parsererror-或-expected" tabindex="-1">问题 3：<code>ParserError</code> 或 <code>Expected &#39;;&#39;</code> <a class="header-anchor" href="#问题-3-parsererror-或-expected" aria-label="Permalink to &quot;问题 3：`ParserError` 或 `Expected &#39;;&#39;`&quot;">​</a></h3><p>Solidity 很在意括号和分号。下面是<strong>错误示例</strong>：</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> public</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> number</span></span></code></pre></div><p>正确的是：</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> public</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> number;</span></span></code></pre></div><p>若复制代码后出现奇怪符号，检查是不是把中文引号 <code>“ ”</code> 当作 Solidity 字符串的英文引号 <code>&quot; &quot;</code>。</p><h3 id="问题-4-编译通过-为什么没有-deploy-按钮" tabindex="-1">问题 4：编译通过，为什么没有 Deploy 按钮？ <a class="header-anchor" href="#问题-4-编译通过-为什么没有-deploy-按钮" aria-label="Permalink to &quot;问题 4：编译通过，为什么没有 Deploy 按钮？&quot;">​</a></h3><p>到 <strong>Deploy &amp; Run Transactions</strong> 面板检查：</p><ol><li><strong>Environment</strong> 是否选择 Remix VM。</li><li><strong>Contract</strong> 下拉框是否选择了刚刚编译的合约。</li><li>是否在前一个页面只新建文件、却没有执行编译。</li></ol><p>注意：点击 Deploy 是<strong>创建一个新的合约实例</strong>。每次重新部署都会得到一个新实例，旧实例的状态不会自动复制到新合约。</p><h3 id="问题-5-我点了-increment-为什么-number-不变" tabindex="-1">问题 5：我点了 increment，为什么 number 不变？ <a class="header-anchor" href="#问题-5-我点了-increment-为什么-number-不变" aria-label="Permalink to &quot;问题 5：我点了 increment，为什么 number 不变？&quot;">​</a></h3><p>按顺序排查：</p><ol><li>Deployed Contracts 中是否展开了<strong>同一个实例</strong>？</li><li>是否真正点击了 <strong>increment</strong>，而不是只点 <code>number</code>？</li><li>Remix 终端是否显示交易失败？</li><li>是否切换了虚拟环境或刷新导致实例变化？</li></ol><p>正确的观察顺序：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>部署 → 读 number() 得到 0</span></span>\n<span class="line"><span>    → 点 increment()</span></span>\n<span class="line"><span>    → 再读 number() 得到 1</span></span>\n<span class="line"><span>    → 点 increment()</span></span>\n<span class="line"><span>    → 再读 number() 得到 2</span></span></code></pre></div><h3 id="问题-6-revert-是不是代码坏了" tabindex="-1">问题 6：<code>revert</code> 是不是代码坏了？ <a class="header-anchor" href="#问题-6-revert-是不是代码坏了" aria-label="Permalink to &quot;问题 6：`revert` 是不是代码坏了？&quot;">​</a></h3><p>不一定。假设 <code>reset()</code> 只允许 owner 调用，其他账号尝试调用时，<strong>失败恰恰是预期结果</strong>。</p><p>判断故障先看三个问题：</p><ul><li><strong>由哪个 Account 发起</strong>？</li><li><strong>调用前合约是什么状态</strong>？</li><li><strong>错误是编译错误还是执行过程中 revert</strong>？</li></ul><p>如果是你设计的“无权操作应被拒绝”，测试出现 revert 反而说明权限规则生效。</p><h3 id="问题-7-我刷新网页后找不到原来的合约" tabindex="-1">问题 7：我刷新网页后找不到原来的合约 <a class="header-anchor" href="#问题-7-我刷新网页后找不到原来的合约" aria-label="Permalink to &quot;问题 7：我刷新网页后找不到原来的合约&quot;">​</a></h3><p>Remix VM 属于虚拟实验环境，不应当作为可靠持久账本。重置或切换工作区、环境等操作可能使之前的实例不再可用。</p><p>此时重新编译、重新部署，再按课文完成一次 0 → 1 → 2，不要为了找旧测试数据而连接真实钱包。</p><h2 id="二、foundry-中最常见的-5-种问题" tabindex="-1">二、Foundry 中最常见的 5 种问题 <a class="header-anchor" href="#二、foundry-中最常见的-5-种问题" aria-label="Permalink to &quot;二、Foundry 中最常见的 5 种问题&quot;">​</a></h2><h3 id="问题-1-终端提示-forge-command-not-found" tabindex="-1">问题 1：终端提示 <code>forge: command not found</code> <a class="header-anchor" href="#问题-1-终端提示-forge-command-not-found" aria-label="Permalink to &quot;问题 1：终端提示 `forge: command not found`&quot;">​</a></h3><p>它不是“合约代码错了”，而是系统找不到 Foundry 可执行程序。依次检查：</p><ol><li>是否安装了 Foundry（参照 <a href="https://getfoundry.sh/introduction/installation/" target="_blank" rel="noreferrer">官方安装指引</a>）。</li><li>是否重新打开终端或加载了对应的 PATH。</li><li>是否在 Windows PowerShell 里误用了 Linux / WSL2 的安装步骤。</li></ol><p>先运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>只有能输出版本信息后，再执行测试。</p><h3 id="问题-2-找不到-foundry-toml、src-、test" tabindex="-1">问题 2：找不到 <code>foundry.toml</code>、<code>src/</code>、<code>test/</code> <a class="header-anchor" href="#问题-2-找不到-foundry-toml、src-、test" aria-label="Permalink to &quot;问题 2：找不到 `foundry.toml`、`src/`、`test/`&quot;">​</a></h3><p>很可能不在教程示例目录。假设你已经位于仓库根目录，执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/foundry</span></span></code></pre></div><p>之后应该能看到 <code>foundry.toml</code>。如果已经在 <code>examples/foundry</code> 中，<strong>不要再执行一次相同的 cd</strong>，否则会找不到目录。</p><h3 id="问题-3-首次编译一直失败或无法下载编译器" tabindex="-1">问题 3：首次编译一直失败或无法下载编译器 <a class="header-anchor" href="#问题-3-首次编译一直失败或无法下载编译器" aria-label="Permalink to &quot;问题 3：首次编译一直失败或无法下载编译器&quot;">​</a></h3><p>本仓库 <code>foundry.toml</code> 使用 <code>solc_version = &quot;0.8.26&quot;</code>。初次运行若缺少对应编译器，可能需要获取它。</p><p>如果机器无法联网、下载失败，先确认是否处于离线环境。<strong>不要为了修复编译器下载问题，执行来历不明的 curl/bash 一键脚本，更不需要提供任何钱包私钥。</strong></p><h3 id="问题-4-forge-test-vv-有-fail" tabindex="-1">问题 4：<code>forge test -vv</code> 有 FAIL <a class="header-anchor" href="#问题-4-forge-test-vv-有-fail" aria-label="Permalink to &quot;问题 4：`forge test -vv` 有 FAIL&quot;">​</a></h3><p>不要立刻把测试删除、或者把 <code>require</code> 全改成 true。</p><p>试着先定位失败用例：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --match-test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> testOwnerCanReset</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -vvvv</span></span></code></pre></div><p>第二条命令输出更多调用轨迹。将测试名称替换成你实际看到的失败测试名。</p><p>请记录四项：</p><table tabindex="0"><thead><tr><th>需要记录的内容</th><th>为什么</th></tr></thead><tbody><tr><td>失败的测试名</td><td>先知道是哪条规则不满足</td></tr><tr><td>预期值</td><td>比如 count 应是 3</td></tr><tr><td>实际值或 revert</td><td>判断行为与预期的差异</td></tr><tr><td>使用的账户与时间</td><td>排查权限和到期边界问题</td></tr></tbody></table><h3 id="问题-5-编译成功是不是等于合约安全" tabindex="-1">问题 5：编译成功是不是等于合约安全？ <a class="header-anchor" href="#问题-5-编译成功是不是等于合约安全" aria-label="Permalink to &quot;问题 5：编译成功是不是等于合约安全？&quot;">​</a></h3><p>不是。</p><ul><li><strong>编译通过</strong>：语法、类型检查等可以生成字节码。</li><li><strong>测试通过</strong>：你写出的那些测试断言当前通过。</li><li><strong>专业审计通过</strong>：另外的完整安全评估过程。</li></ul><p>尤其涉及真实资金时，不能用一条“测试通过”消息替代安全验证。</p><h2 id="三、几个经常把新人绕晕的术语问题" tabindex="-1">三、几个经常把新人绕晕的术语问题 <a class="header-anchor" href="#三、几个经常把新人绕晕的术语问题" aria-label="Permalink to &quot;三、几个经常把新人绕晕的术语问题&quot;">​</a></h2><h3 id="我能否先学习-solidity-完全不理解交易" tabindex="-1">我能否先学习 Solidity，完全不理解交易？ <a class="header-anchor" href="#我能否先学习-solidity-完全不理解交易" aria-label="Permalink to &quot;我能否先学习 Solidity，完全不理解交易？&quot;">​</a></h3><p>可以先学语法，但很快就会误解“读变量”和“改变量”的区别。建议先看 <a href="/00-start/">00-1 基础故事</a> 和 <a href="/00-start/environment">00-2 Remix 实验</a>，至少能区分读取调用与交易。</p><h3 id="为什么源码改了、重新编译后-旧合约还是原样" tabindex="-1">为什么源码改了、重新编译后，旧合约还是原样？ <a class="header-anchor" href="#为什么源码改了、重新编译后-旧合约还是原样" aria-label="Permalink to &quot;为什么源码改了、重新编译后，旧合约还是原样？&quot;">​</a></h3><p>因为 <strong>编译的是本地源码，部署的是链上的独立实例</strong>。旧合约不会自动热更新。你需要再次部署新实例，或者以后专门学习受限的可升级架构。</p><h3 id="为什么钱包显示了交易哈希-业务页面还在-等待" tabindex="-1">为什么钱包显示了交易哈希，业务页面还在“等待”？ <a class="header-anchor" href="#为什么钱包显示了交易哈希-业务页面还在-等待" aria-label="Permalink to &quot;为什么钱包显示了交易哈希，业务页面还在“等待”？&quot;">​</a></h3><p>交易哈希只是交易标识；还需要检查回执、执行成功与所需确认。不要把“已经广播”当成“已经完成”。</p><h3 id="合约里的-private-能保护身份证号吗" tabindex="-1">合约里的 private 能保护身份证号吗？ <a class="header-anchor" href="#合约里的-private-能保护身份证号吗" aria-label="Permalink to &quot;合约里的 private 能保护身份证号吗？&quot;">​</a></h3><p>不能。链上状态一般不应存储这类敏感内容，<code>private</code> 只限制合约代码层面的访问，<strong>不是加密</strong>。</p><h3 id="不懂英语可以继续吗" tabindex="-1">不懂英语可以继续吗？ <a class="header-anchor" href="#不懂英语可以继续吗" aria-label="Permalink to &quot;不懂英语可以继续吗？&quot;">​</a></h3><p>可以。先理解英文词在场景中的意思，不必一开始背全部单词。打开 <a href="/00-start/glossary">零基础术语词典</a>，结合正在操作的按钮一起理解。</p><h2 id="四、如何把错误描述清楚" tabindex="-1">四、如何把错误描述清楚？ <a class="header-anchor" href="#四、如何把错误描述清楚" aria-label="Permalink to &quot;四、如何把错误描述清楚？&quot;">​</a></h2><p>如果自己仍解决不了，可以按下面的格式记录，方便排查：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我在哪一课：</span></span>\n<span class="line"><span>使用的是 Remix VM / Foundry / Anvil：</span></span>\n<span class="line"><span>我执行的按钮或命令：</span></span>\n<span class="line"><span>我原本希望看到什么：</span></span>\n<span class="line"><span>实际出现什么错误（粘贴原始错误文本）：</span></span>\n<span class="line"><span>我刚才改过哪些代码：</span></span></code></pre></div><p><strong>不要附带私钥、助记词、真实钱包恢复信息或真实资金转账材料。</strong></p><p>最后复习一次顺序：先确保环境对，再确保编译通过，再验证运行结果，最后才处理复杂的资金和权限问题。</p><p><a href="/roadmap">返回入门路线</a> · <a href="/01-solidity/">继续 Solidity</a></p>',80)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
